// lib/app/dashboard/dashboard_page.dart
import 'package:mad_flutter_practicum/app/app.dart';
import 'package:mad_flutter_practicum/domain/domain.dart';

class DashboardPage extends StatefulWidget {
  const DashboardPage({super.key});

  @override
  State<DashboardPage> createState() => _DashboardPageState();
}

class _DashboardPageState extends State<DashboardPage> with SingleTickerProviderStateMixin {
  late Future<Map<String, dynamic>> _dashboardFuture;

  late final AnimationController _fadeController;

  @override
  void initState() {
    super.initState();
    _initAnimation();
    _initData();
  }

  @override
  void dispose() {
    _fadeController.dispose();
    super.dispose();
  }

  void _initAnimation() {
    _fadeController = AnimationController(
      duration: const Duration(milliseconds: 400),
      vsync: this,
    );
  }

  void _initData() {
    final currencyRepository = context.read<CurrencyRepository>();
    final newsRepository = context.read<NewsRepository>();

    final currencyFuture = currencyRepository.fetchRates(const CurrencyPageRequest(base: 'USD'));
    final newsFuture = newsRepository.loadNewsFeed(const NewsFeedFilter(forceRefresh: true));

    _dashboardFuture = Future.wait([currencyFuture, newsFuture]).then((List<dynamic> results) {
      final CurrencyPage currencyPage = results[0] as CurrencyPage;
      final List<NewsModel> newsList = results[1] as List<NewsModel>;

      _fadeController.forward();

      return <String, dynamic>{
        'currencies': currencyPage.items,
        'news': newsList,
      };
    });
  }

  @override
  Widget build(BuildContext context) {
    final AppLocalizations loc = context.loc;

    return Scaffold(
      appBar: AppBar(title: Text(loc.dashboard)),
      body: FutureBuilder<Map<String, dynamic>>(
        future: _dashboardFuture,
        builder: (BuildContext context, AsyncSnapshot<Map<String, dynamic>> snapshot) {
          if (!snapshot.hasData) {
            return const Center(child: CircularProgressIndicator());
          }

          final List<CurrencyModel> currencies = snapshot.data!['currencies'] as List<CurrencyModel>;
          final List<NewsModel> news = snapshot.data!['news'] as List<NewsModel>;
          final ValueNotifier<List<CurrencyModel>> filteredCurrenciesNotifier = ValueNotifier(currencies);

          return FadeTransition(
            opacity: _fadeController.view,
            child: ListView(
              padding: const EdgeInsets.fromLTRB(22, 16, 22, 40),
              children: [
                if (currencies.isNotEmpty) ...[
                  Text(loc.currencyRate, style: context.fonts.semiBold16),
                  const SizedBox(height: 10),
                  ValueListenableBuilder<List<CurrencyModel>>(
                    valueListenable: filteredCurrenciesNotifier,
                    builder: (BuildContext context, List<CurrencyModel> data, _) {
                      return Column(
                        children: [
                          for (int index = 0; index < data.length; index++) ...[
                            if (index > 0) const SizedBox(height: 10),
                            CurrencyCard(model: data[index]),
                          ],
                        ],
                      );
                    },
                  ),
                ],
                if (news.isNotEmpty) ...[
                  const SizedBox(height: 24),
                  Text(loc.news, style: context.fonts.semiBold16),
                  const SizedBox(height: 10),
                  Column(
                    children: [
                      for (int index = 0; index < news.length; index++) ...[
                        if (index > 0) const SizedBox(height: 10),
                        NewsCard(model: news[index]),
                      ],
                    ],
                  ),
                ],
              ],
            ),
          );
        },
      ),
    );
  }
}
