import 'package:flutter/material.dart';
import 'package:mad_flutter_practicum/app/app.dart';
import 'package:mad_flutter_practicum/domain/domain.dart';

class DashboardPage extends StatefulWidget {
  const DashboardPage({super.key});

  @override
  State<DashboardPage> createState() => _DashboardPageState();
}

class _DashboardPageState extends State<DashboardPage> with SingleTickerProviderStateMixin {
  late Future<(List<CurrencyModel>, List<NewsModel>)> _dataFuture;

  @override
  void initState() {
    super.initState();
    _initData();
  }

  void _initData() {
    final currencyRepository = context.read<CurrencyRepository>();
    final newsRepository = context.read<NewsRepository>();

    _dataFuture = Future.wait([
      currencyRepository.fetchRates(const CurrencyPageRequest(base: 'USD')),
      newsRepository.loadNewsFeed(const NewsFeedFilter(forceRefresh: true)),
    ]).then((List<dynamic> results) {
      return (
        (results[0] as CurrencyPage).items,
        results[1] as List<NewsModel>,
      );
    });
  }

  @override
  Widget build(BuildContext context) {
    final AppLocalizations loc = context.loc;
    final ThemeFonts fonts = context.fonts;
    final ThemeColors colors = context.colors;

    return Scaffold(
      appBar: AppBar(title: Text(loc.dashboard)),
      body: FutureBuilder<(List<CurrencyModel>, List<NewsModel>)>(
        future: _dataFuture,
        builder: (BuildContext context, AsyncSnapshot<(List<CurrencyModel>, List<NewsModel>)> snapshot) {
          if (!snapshot.hasData) {
            return const Center(
              child: CircularProgressIndicator(),
            );
          }

          final List<CurrencyModel> currencies = snapshot.data!.$1;
          final List<NewsModel> newsItems = snapshot.data!.$2;

          return ListView(
            padding: const EdgeInsets.symmetric(vertical: 8),
            children: [
              Padding(
                padding: const EdgeInsets.fromLTRB(16, 8, 16, 4),
                child: Text(
                  loc.currencyRate,
                  style: fonts.semiBold12.copyWith(color: colors.secondary),
                ),
              ),
              if (currencies.isEmpty)
                Padding(
                  padding: const EdgeInsets.all(16),
                  child: Text(loc.search, style: fonts.regular12.copyWith(color: colors.tin)),
                )
              else ...[
                Padding(
                  padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 4),
                  child: ListView.builder(
                    shrinkWrap: true,
                    physics: const NeverScrollableScrollPhysics(),
                    itemCount: currencies.length,
                    itemBuilder: (BuildContext context, int index) {
                      final CurrencyModel currency = currencies[index];
                      return Padding(
                        key: ValueKey(currency.id),
                        padding: EdgeInsets.only(top: index == 0 ? 12 : 8, bottom: 8),
                        child: _CurrencyCard(model: currency),
                      );
                    },
                  ),
                ),
              ],
              const Divider(height: 16),
              Padding(
                padding: const EdgeInsets.fromLTRB(16, 4, 16, 4),
                child: Text(
                  loc.news,
                  style: fonts.semiBold12.copyWith(color: colors.secondary),
                ),
              ),
              if (newsItems.isEmpty)
                Padding(
                  padding: const EdgeInsets.all(16),
                  child: Text(loc.search, style: fonts.regular12.copyWith(color: colors.tin)),
                )
              else ...[
                Padding(
                  padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 4),
                  child: ListView.builder(
                    shrinkWrap: true,
                    physics: const NeverScrollableScrollPhysics(),
                    itemCount: newsItems.length,
                    itemBuilder: (BuildContext context, int index) {
                      final NewsModel news = newsItems[index];
                      return Padding(
                        key: ValueKey(news.link),
                        padding: EdgeInsets.only(top: index == 0 ? 12 : 8, bottom: 8),
                        child: _NewsCard(model: news),
                      );
                    },
                  ),
                ),
              ],
            ],
          );
        },
      ),
    );
  }
}

class _CurrencyCard extends StatelessWidget {
