void main() {
  group('DashboardPage', () {
    final MockCurrencyRepository mockCurrencyRepository = MockCurrencyRepository();
    final MockNewsRepository mockNewsRepository = MockNewsRepository();

    late Widget dashboardWidget;

    setUp(() {
      dashboardWidget = buildWidget(
        providers: [
          Provider<CurrencyRepository>.value(value: mockCurrencyRepository),
          Provider<NewsRepository>.value(value: mockNewsRepository),
        ],
        child: const DashboardPage(),
      );

      when(mockCurrencyRepository.fetchRates(any)).thenAnswer((_) async => const CurrencyPage(items: [], page: 0, hasMore: false));
      when(mockNewsRepository.loadNewsFeed(any)).thenAnswer((_) async => <NewsModel>[]);
    });

    testWidgets('should show CircularProgressIndicator while loading', (WidgetTester tester) async {
      final StreamController<CurrencyPage> currencyStream = StreamController<CurrencyPage>();
      final StreamController<List<NewsModel>> newsStream = StreamController<List<NewsModel>>();

      when(mockCurrencyRepository.fetchRates(any)).thenAnswer((_) => currencyStream.stream.first);
      when(mockNewsRepository.loadNewsFeed(any)).thenAnswer((_) => newsStream.stream.first);

      await tester.pumpWidget(dashboardWidget);
      await tester.pump(const Duration(milliseconds: 100));

      expect(find.byType(CircularProgressIndicator), findsOneWidget);

      currencyStream.add(const CurrencyPage(items: [], page: 0, hasMore: false));
      newsStream.add(<NewsModel>[]);
      await tester.pumpAndSettle();

      currencyStream.close();
      newsStream.close();
    });

    testWidgets('should display currencies and news after loading', (WidgetTester tester) async {
      const List<CurrencyModel> currencies = <CurrencyModel>[
        CurrencyModel(id: '1', nominal: 1, name: 'Dollar', symbol: '$', value: 60.99, previousValue: 60.5),
