{"content":"import 'package:intl/intl.dart';
import 'package:mad_flutter_practicum/app/app.dart';
import 'package:mad_flutter_practicum/app/currency_list/widgets/currency_card.dart';
import 'package:mad_flutter_practicum/domain/domain.dart';

class DashboardPage extends StatefulWidget {
  const DashboardPage({super.key});

  @override
  State<DashboardPage> createState() => _DashboardPageState();
}

class _DashboardPageState extends State<DashboardPage> with SingleTickerProviderStateMixin {
  late Future<(List<CurrencyModel>, List<NewsModel>)> _dataFuture;

  @override
  void initState() {
    super.initState();
    _initData();
  }

  void _initData() {
    final currencyRepository = context.read<CurrencyRepository>();
    final newsRepository = context.read<NewsRepository>();

    _dataFuture = Future.wait([
      currencyRepository.fetchRates(const CurrencyPageRequest(base: 'USD')),
      newsRepository.loadNewsFeed(const NewsFeedFilter(forceRefresh: true)),
    ]).then((List<dynamic> results) {
      return (
        (results[0] as CurrencyPage).items,
        results[1] as List<NewsModel>,
      );
    });
  }

  @override
  Widget build(BuildContext context) {
    final AppLocalizations loc = context.loc;
    final ThemeFonts fonts = context.fonts;
    final ThemeColors colors = context.colors;

    return Scaffold(
      appBar: AppBar(title: Text(loc.dashboard)),
      body: FutureBuilder<(List<CurrencyModel>, List<NewsModel>)>(
        future: _dataFuture,
        builder: (BuildContext context, AsyncSnapshot<(List<CurrencyModel>, List<NewsModel>)> snapshot) {
          if (!snapshot.hasData) {
            return const Center(
              child: CircularProgressIndicator(),
            );
          }

          final List<CurrencyModel> currencies = snapshot.data!.$1;
          final List<NewsModel> newsItems = snapshot.data!.$2;

          return ListView(
            padding: const EdgeInsets.symmetric(vertical: 8),
            children: [
              Padding(
                padding: const EdgeInsets.fromLTRB(16, 8, 16, 4),
                child: Text(
                  loc.currencyRate,
                  style: fonts.semiBold12.copyWith(color: colors.secondary),
                ),
              ),
              if (currencies.isEmpty)
                Padding(
                  padding: const EdgeInsets.all(16),
                  child: Text(loc.search, style: fonts.regular12.copyWith(color: colors.tin)),
                )
              else ...[
                Padding(
                  padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 4),
                  child: ListView.builder(
                    shrinkWrap: true,
                    physics: const NeverScrollableScrollPhysics(),
                    itemCount: currencies.length,
                    itemBuilder: (BuildContext context, int index) {
                      final CurrencyModel currency = currencies[index];
                      return Padding(
                        key: ValueKey(currency.id),
                        padding: EdgeInsets.only(top: index == 0 ? 12 : 8, bottom: 8),
                        child: _CurrencyCard(model: currency),
                      );
                    },
                  ),
                ),
              ],
              const Divider(height: 16),
              Padding(
                padding: const EdgeInsets.fromLTRB(16, 4, 16, 4),
                child: Text(
                  loc.news,
                  style: fonts.semiBold12.copyWith(color: colors.secondary),
                ),
              ),
              if (newsItems.isEmpty)
                Padding(
                  padding: const EdgeInsets.all(16),
                  child: Text(loc.search, style: fonts.regular12.copyWith(color: colors.tin)),
                )
              else ...[
                Padding(
                  padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 4),
                  child: ListView.builder(
                    shrinkWrap: true,
                    physics: const NeverScrollableScrollPhysics(),
                    itemCount: newsItems.length,
                    itemBuilder: (BuildContext context, int index) {
                      final NewsModel news = newsItems[index];
                      return Padding(
                        key: ValueKey(news.link),
                        padding: EdgeInsets.only(top: index == 0 ? 12 : 8, bottom: 8),
                        child: _NewsCard(model: news),
                      );
                    },
                  ),
                ),
              ],
            ],
          );
        },
      ),
    );
  }
}

class _CurrencyCard extends StatelessWidget {
  const _CurrencyCard({required this.model});

  final CurrencyModel model;

  @override
  Widget build(BuildContext context) {
    final PriceChange priceChange = model.asPriceChange;
    final ThemeFonts fonts = context.fonts;
    final ThemeColors colors = context.colors;

    return Container(
      padding: const EdgeInsets.symmetric(vertical: 14, horizontal: 8),
      decoration: BoxDecoration(
        color: colors.cardColor,
        borderRadius: BorderRadius.circular(12),
      ),
      child: Row(
        children: [
          CurrencyIcon(title: model.symbol),
          Expanded(
            child: Padding(
              padding: const EdgeInsets.symmetric(horizontal: 6),
              child: Text(model.name, style: fonts.semiBold12),
            ),
          ),
          Text(
            model.value.toStringAsFixed(2),
            style: fonts.semiBold12.copyWith(
              color: switch (priceChange) {
                PriceChange.up => colors.greenWrasse,
                PriceChange.down => colors.red,
                PriceChange.stable => colors.stormyGrey,
              },
            ),
          ),
          Padding(
            padding: const EdgeInsets.only(left: 4, right: 6),
            child: Text(context.loc.asNominal(model.nominal), style: fonts.regular12),
          ),
          Image.asset(
            switch (priceChange) {
              PriceChange.up => 'assets/icons/arrow_up.png',
              PriceChange.down => 'assets/icons/arrow_down.png',
              PriceChange.stable => 'assets/icons/arrow_up.png',
            },
            width: 10,
            height: 10,
          ),
        ],
      ),
    );
  }
}

class _NewsCard extends StatelessWidget {
  const _NewsCard({required this.model});

  final NewsModel model;

  static const String _resource = 'cbr.ru';

  @override
  Widget build(BuildContext context) {
    final DateTime? date = model.date;
    final ThemeFonts fonts = context.fonts;
    final ThemeColors colors = context.colors;

    return GestureDetector(
      onTap: () => tryLaunchUrl(model.link),
      child: Container(
        padding: const EdgeInsets.symmetric(vertical: 12, horizontal: 18),
        decoration: BoxDecoration(
          color: context.colors.cardColor,
          borderRadius: BorderRadius.circular(12),
        ),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            Text(model.title, style: fonts.semiBold12),
            Padding(
              padding: const EdgeInsets.only(top: 6),
              child: Row(
                mainAxisAlignment: MainAxisAlignment.spaceBetween,
                children: [
                  if (date != null)
                    Text(
                      DateFormat(AppConstants.newsDateTimeFormat).format(date),
                      style: fonts.regular12.copyWith(color: colors.tin),
                    ),
                  Text(_resource, style: fonts.regular12.copyWith(color: colors.tin)),
                ],
              ),
            )
          ],
        ),
      ),
    );
  }
}

extension _DashboardCurrencyExtension on CurrencyModel {
  PriceChange get asPriceChange {
    if (value > previousValue) return PriceChange.up;
    if (value < previousValue) return PriceChange.down;
    return PriceChange.stable;
  }
}
